$q=db()->prepare('SELECT id,nome,email,perfil,situacao FROM usuarios WHERE id=?');$q->bind_param('i',$id);$q->execute();$u=$q->get_result()->fetch_assoc();if(!$u||$u['perfil']==='admin')exit('Usuário inválido.');
